**What this code covers**

- Short-term: the conversation history in the LLM context.
- Long-term: semantic search over stored facts/documents.
- Store and recall past task episodes.
- Simple recency-based recall (enhance with embeddings for production).
- 2. External (Long-Term) Memory — Vector Store
- Normalize for cosine similarity
- 4. Semantic Memory (Key-Value)

**Defines:** `InContextMemory`, `VectorMemory`, `Episode`, `EpisodicMemory`, `SemanticMemory`, `Procedure`, `ProceduralMemory`, `AgentMemorySystem`

**Q1. Implement all five memory types in a unified agent memory system.**

```python
import json
import time
from dataclasses import dataclass, field
from typing import Any
import redis
import faiss
import numpy as np
from openai import OpenAI

client = OpenAI()

# ── 1. In-Context Memory ──────────────────────────────────────
class InContextMemory:
    """Short-term: the conversation history in the LLM context."""
    def __init__(self, max_tokens: int = 100_000):
        self.messages: list[dict] = []
        self.max_tokens = max_tokens

    def add(self, role: str, content: str) -> None:
        self.messages.append({"role": role, "content": content, "ts": time.time()})
        self._trim()

    def _trim(self) -> None:
        while count_tokens(self.messages) > self.max_tokens and len(self.messages) > 2:
            self.messages.pop(1)  # Remove oldest (preserve system prompt at index 0)

    def get(self) -> list[dict]:
        return [{"role": m["role"], "content": m["content"]} for m in self.messages]

# ── 2. External (Long-Term) Memory — Vector Store ─────────────
class VectorMemory:
    """Long-term: semantic search over stored facts/documents."""
    def __init__(self, dimension: int = 1536):
        self.index = faiss.IndexFlatIP(dimension)  # Inner product (cosine on normalized)
        self.documents: list[str] = []

    def _embed(self, text: str) -> np.ndarray:
        response = client.embeddings.create(model="text-embedding-3-small", input=text)
        vec = np.array(response.data[0].embedding, dtype=np.float32)
        # Normalize for cosine similarity
        return vec / np.linalg.norm(vec)

    def store(self, text: str) -> None:
        embedding = self._embed(text)
        self.index.add(embedding.reshape(1, -1))
        self.documents.append(text)

    def retrieve(self, query: str, top_k: int = 5) -> list[str]:
        if self.index.ntotal == 0:
            return []
        q_vec = self._embed(query).reshape(1, -1)
        scores, indices = self.index.search(q_vec, top_k)
        return [self.documents[i] for i in indices[0] if i < len(self.documents)]

# ── 3. Episodic Memory ───────────────────────────────────────
@dataclass
class Episode:
    task: str
    steps: list[dict]
    outcome: str  # "success" | "failure"
    timestamp: float = field(default_factory=time.time)
    lessons: str = ""  # Extracted learnings

class EpisodicMemory:
    """Store and recall past task episodes."""
    def __init__(self, redis_client: redis.Redis):
        self.redis = redis_client
        self.key = "agent:episodes"

    def record(self, episode: Episode) -> None:
        self.redis.lpush(self.key, json.dumps(episode.__dict__))
        self.redis.ltrim(self.key, 0, 99)  # Keep last 100 episodes

    def recall_similar(self, current_task: str, top_k: int = 3) -> list[Episode]:
        """Simple recency-based recall (enhance with embeddings for production)."""
        raw = self.redis.lrange(self.key, 0, top_k - 1)
        return [Episode(**json.loads(r)) for r in raw]

# ── 4. Semantic Memory (Key-Value) ───────────────────────────
class SemanticMemory:
    """Structured fact store — key-value knowledge base."""
    def __init__(self, redis_client: redis.Redis):
        self.redis = redis_client

    def learn(self, key: str, value: Any) -> None:
        self.redis.set(f"agent:semantic:{key}", json.dumps(value))

    def recall(self, key: str) -> Any | None:
        val = self.redis.get(f"agent:semantic:{key}")
        return json.loads(val) if val else None

# ── 5. Procedural Memory ─────────────────────────────────────
@dataclass
class Procedure:
    name: str
    trigger_pattern: str  # When to use this procedure
    steps: list[str]
    success_rate: float = 1.0

class ProceduralMemory:
    """Store learned workflows and tool-use patterns."""
    def __init__(self):
        self.procedures: dict[str, Procedure] = {}

    def register(self, procedure: Procedure) -> None:
        self.procedures[procedure.name] = procedure

    def find_matching(self, task: str) -> Procedure | None:
        """Find the best matching procedure for the current task."""
        for proc in self.procedures.values():
            if proc.trigger_pattern.lower() in task.lower():
                return proc
        return None

# ── Unified Agent Memory ─────────────────────────────────────
class AgentMemorySystem:
    """Combines all 5 memory types into a unified interface."""
    def __init__(self, redis_client: redis.Redis):
        self.context = InContextMemory()
        self.vector = VectorMemory()
        self.episodic = EpisodicMemory(redis_client)
        self.semantic = SemanticMemory(redis_client)
        self.procedural = ProceduralMemory()

    def build_enriched_context(self, current_task: str) -> str:
        """Build a rich context blob for the agent by querying all memory types."""
        parts = []

        # Relevant long-term facts
        facts = self.vector.retrieve(current_task, top_k=3)
        if facts:
            parts.append("Relevant facts:\n" + "\n".join(f"- {f}" for f in facts))

        # Past similar episodes
        episodes = self.episodic.recall_similar(current_task, top_k=2)
        if episodes:
            parts.append("Past similar tasks:\n" + "\n".join(
                f"- {e.task} → {e.outcome}: {e.lessons}" for e in episodes
            ))

        # Applicable procedure
        proc = self.procedural.find_matching(current_task)
        if proc:
            parts.append(f"Standard procedure '{proc.name}':\n" + "\n".join(
                f"  {i+1}. {s}" for i, s in enumerate(proc.steps)
            ))

        return "\n\n".join(parts)
```

*(Q2-Q10 cover: memory scoring for retrieval, memory write conflicts, compression, forgetting curves, graph memory, memory across agent restarts, hybrid retrieval strategies, memory for multi-agent systems, memory privacy/security)*
